def acid_to_shift(Ca, Cb, dpH):
    # Henderson-Hasselbalch: pH = pKa + log10(base/acid).
    # After adding x of strong acid: base -> Cb - x, acid -> Ca + x, and the ratio must be
    # 10**(-dpH) times the starting ratio Cb/Ca.
    r = (Cb / Ca) * 10 ** (-dpH)
    return (Cb - r * Ca) / (1 + r)
